import {useCallback,useEffect,useMemo,useState} from 'react';
import type {ReactNode} from 'react';
import {Activity,ArrowDownToLine,ArrowLeftRight,ArrowRight,ArrowUpRight,BarChart3,Bookmark,Check,ChevronDown,ChevronLeft,ChevronRight,Clock3,Database,Globe2,Grid2X2,Info,Layers3,LoaderCircle,LockKeyhole,Map,Plane,Plus,Radar,Radio,Terminal,Link,RefreshCw,Search,Settings2,Share2,ShieldCheck,SlidersHorizontal,Sun,Trash2,Waypoints,X} from 'lucide-react';
import {api,query,setCsrf} from './api';
import {Chart,chartBase,palette} from './Chart';
import type {Analytics,Breakdown,Comparison,Filters,Page,Rows,Service,Settings,Status,Table,UpdateStatus} from './types';
import {dateTime,filterParams,londonEpoch,londonInput,metricHelp,metricName,number,windowFor} from './time';
const defaults:Filters={metric:'aircraft',preset:'24',duration:'46',unit:'hours',start:londonInput(Date.now()/1000-86400),end:londonInput(),group:'hour',stat:'count',category:'',aircraft_type:'',operator:'',icao:'',callsign:'',month:'',exclude_partial:false,session_gap:30,fold:'earlier'};
const titles:Record<Page,string>={home:'Overview',explore:'Explore',compare:'Compare',patterns:'Patterns',data:'Database',settings:'Settings'};
const icons={home:Grid2X2,explore:BarChart3,compare:ArrowLeftRight,patterns:Layers3,data:Database,settings:Settings2};
function useResource<T>(loader:()=>Promise<T>,key:string){const [data,setData]=useState<T|null>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(true);const [revision,setRevision]=useState(0);useEffect(()=>{let alive=true;setLoading(true);setError('');loader().then(d=>{if(alive)setData(d);}).catch(e=>{if(alive)setError(e.message);}).finally(()=>{if(alive)setLoading(false);});return()=>{alive=false;};},[key,revision]);return {data,error,loading,reload:()=>setRevision(x=>x+1)};}
function Notice({children,error=false}:{children:ReactNode;error?:boolean}){return <div className={error?'notice error-state':'notice'} role={error?'alert':'status'}><Info size={16}/><span>{children}</span></div>;}
function LoadState({loading,error,empty=false}:{loading:boolean;error:string;empty?:boolean}){if(error)return <Notice error>{error}</Notice>;if(loading)return <div className="loading"><LoaderCircle className="spin" size={20}/> Loading your airspace…</div>;if(empty)return <div className="empty-state"><Radar size={30}/><h3>No observations in this window</h3><p>Try another period. Unavailable history is never filled with invented traffic.</p></div>;return null;}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}</label>;}
function initialFilters(){try{const raw=new URLSearchParams(location.search).get('view');if(raw)return {...defaults,...JSON.parse(raw)} as Filters;}catch{/* invalid share links use defaults */}return defaults;}
function initialPage():Page {const p=location.hash.slice(1) as Page;return Object.hasOwn(titles,p)?p:'home';}
function saveView(f:Filters){const label=window.prompt('Name this saved view','My airspace view');if(!label)return;try{const views=JSON.parse(localStorage.getItem('airspace-views')||'[]');localStorage.setItem('airspace-views',JSON.stringify([...views,{label,filters:f}].slice(-20)));}catch{/* storage optional */}}
function useAnalytics(f:Filters,status:Status|null,tick=0){const {params,issue}=useMemo(()=>{try{return {params:filterParams(f,status),issue:''};}catch(e){return {params:{},issue:(e as Error).message};}},[JSON.stringify(f),status?.source.first_seen,tick]);const key=JSON.stringify(params)+issue+tick;return useResource<Analytics>(()=>issue?Promise.reject(new Error(issue)):api('/analytics?'+query(params)),key);}
export default function App(){
 const [page,setPage]=useState<Page>(initialPage);const [filters,setFilters]=useState<Filters>(initialFilters);const [tick,setTick]=useState(0);const status=useResource<Status>(()=>api('/status'),String(tick));const settings=useResource<Settings>(()=>api('/settings'),'settings');
 const [auth,setAuth]=useState(false);const [login,setLogin]=useState(false);const [aircraft,setAircraft]=useState('');const [toast,setToast]=useState('');const [clock,setClock]=useState(Date.now());
 useEffect(()=>{api<{authenticated:boolean;csrf_token:string}>('/auth/session').then(r=>{setAuth(r.authenticated);setCsrf(r.csrf_token||'');}).catch(()=>{});const timer=setInterval(()=>setClock(Date.now()),1000);return()=>clearInterval(timer);},[]);
 useEffect(()=>{const timer=setInterval(()=>setTick(x=>x+1),Math.max(30,settings.data?.refresh_seconds||60)*1000);return()=>clearInterval(timer);},[settings.data?.refresh_seconds]);
 useEffect(()=>{const hash=()=>setPage(initialPage());window.addEventListener('hashchange',hash);return()=>window.removeEventListener('hashchange',hash);},[]);
 useEffect(()=>{if(settings.data&&!new URLSearchParams(location.search).has('view'))setFilters(f=>({...f,session_gap:settings.data!.session_gap_minutes}));},[settings.data?.session_gap_minutes]);
 useEffect(()=>{const theme=settings.data?.theme||'dark';document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):theme;},[settings.data?.theme]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(t);},[toast]);
 const navigate=useCallback((p:Page)=>{location.hash=p;setPage(p);window.scrollTo({top:0,behavior:'instant'});},[]);
 const apply=(f:Filters)=>{setFilters(f);const u=new URL(location.href);u.searchParams.set('view',JSON.stringify(f));history.replaceState(null,'',u);};
 const explore=(partial:Partial<Filters>)=>{apply({...filters,...partial});navigate('explore');};
 const guard=()=>{if(auth)return true;setLogin(true);return false;};
 const shared={filters,status:status.data,apply,tick,openAircraft:setAircraft};
 return <div className="app-shell">
  <aside className="sidebar"><a className="brand" href="#home" aria-label="Airspace home"><span className="brand-mark"><Plane size={23}/></span><span>AIRSPACE<small>ANALYTICS</small></span></a><span className="nav-caption">YOUR CONTROL CENTRE</span><nav className="nav" aria-label="Main navigation">{(Object.keys(titles) as Page[]).map(p=>{const Icon=icons[p];return <a key={p} href={'#'+p} className={'nav-link '+(page===p?'active':'')} aria-current={page===p?'page':undefined}><Icon size={19}/><span>{titles[p]}</span>{p==='explore'&&<span className="nav-new">EXPLORE</span>}</a>;})}</nav><div className="sidebar-footer"><div className="connection-indicator"><i className={status.data?.source.connected?'online':''}/><span>{status.data?.source.connected?'History connected':'Source unavailable'}</span></div><p>AERODROME · READ ONLY</p><div className="sidebar-version"><span>Airspace v{status.data?.version||'—'}</span><ShieldCheck size={15}/></div></div></aside>
  <main className="main"><header className="topbar"><div className="breadcrumbs"><span>Workspace</span><ChevronRight size={13}/><strong>{titles[page]}</strong></div><div className="top-actions"><span className="timezone-label"><Globe2 size={14}/> Europe/London</span><button className="icon-button" aria-label="Refresh data" onClick={()=>{setTick(x=>x+1);setToast('Refreshing data');}}><RefreshCw size={17}/></button><button className="button small secondary" onClick={async()=>{if(auth){await api('/auth/logout',{method:'POST'});setAuth(false);setCsrf('');}else setLogin(true);}}><LockKeyhole size={14}/><span>{auth?'Lock settings':'Admin'}</span></button></div></header>
  <div className="page-content">{status.data?.demo&&<div className="demo-banner"><Radar size={15}/><strong>DEMO WORKSPACE</strong><span>Synthetic aircraft data · your receiver is not connected</span></div>}{status.error&&<Notice error>{status.error}</Notice>}
  {page==='home'&&<Home status={status.data} settings={settings.data} navigate={navigate} explore={explore} tick={tick} clock={clock}/>}
  {page==='explore'&&<Explorer {...shared} toast={setToast}/>}
  {page==='patterns'&&<Patterns {...shared}/>}
  {page==='compare'&&<Compare {...shared}/>}
  {page==='data'&&<DataBrowser status={status.data} openAircraft={setAircraft}/>}
  {page==='settings'&&<SettingsPage settings={settings.data} status={status.data} reload={settings.reload} guard={guard} auth={auth} toast={setToast}/>}
  <footer className="footer-note"><ShieldCheck size={13}/><span>Independent analytics. Your receiver, feeders and Aerodrome history stay untouched.</span><span className="footer-tz">All times Europe/London</span></footer></div></main>
  {login&&<Login onClose={()=>setLogin(false)} onSuccess={()=>{setAuth(true);setLogin(false);setToast('Administrator session unlocked');}}/>}{aircraft&&<AircraftModal icao={aircraft} filters={filters} status={status.data} onClose={()=>setAircraft('')}/>}{toast&&<div className="toast" role="status"><Check size={16}/>{toast}</div>}
 </div>;
}
function Home({status,settings,navigate,explore,tick,clock}:{status:Status|null;settings:Settings|null;navigate:(p:Page)=>void;explore:(f:Partial<Filters>)=>void;tick:number;clock:number}){
 const homeFilters={...defaults,preset:'today'};const result=useAnalytics(homeFilters,status,tick);const a=result.data;const now=new Date(clock);const greeting=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'numeric',hourCycle:'h23'}).format(now))<12?'Good morning':'Welcome to your airspace';
 const age=status?.source.last_seen?Math.max(0,Math.floor(clock/1000-status.source.last_seen)):null;
 return <><section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="live-dot"/> YOUR AIRSPACE, UNDERSTOOD</div><h1>{greeting}<span className="text-mint">.</span></h1><p>One home for your receiver.<br/>A new perspective on every aircraft.</p><div className="hero-meta"><span><Clock3 size={14}/>{new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',weekday:'long',day:'numeric',month:'long'}).format(now)}</span><strong>{new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now)}</strong></div><button className="button primary" onClick={()=>navigate('explore')}>Explore your history <ArrowRight size={17}/></button></div><div className="hero-radar" aria-hidden="true"><div className="radar-ring ring-one"/><div className="radar-ring ring-two"/><div className="radar-ring ring-three"/><div className="radar-cross"/><div className="radar-sweep"/><Plane className="radar-plane" size={30}/><span className="radar-dot dot-one"/><span className="radar-dot dot-two"/><span className="radar-dot dot-three"/><span className="radar-north">N</span><span className="radar-label">HISTORY IN FOCUS</span></div></section>
 <div className="section-heading"><div><span className="eyebrow">THE BIG PICTURE</span><h2>Today at a glance</h2></div><span className="subtle freshness"><span className="live-dot"/>{age===null?'Awaiting source':age<90?'History up to date':`Latest record ${age<3600?Math.floor(age/60)+'m':Math.floor(age/3600)+'h'} ago`}</span></div>
 <LoadState loading={result.loading&&!a} error={result.error}/>{a&&<><Stats data={a} onMetric={metric=>explore({metric,preset:'today'})}/><div className="chart-grid home-charts"><section className="panel"><div className="panel-header"><div><span className="eyebrow">TRAFFIC THROUGH THE DAY</span><h3>Aircraft observed</h3></div><button className="icon-button" onClick={()=>navigate('explore')} aria-label="Open traffic explorer"><ArrowUpRight size={19}/></button></div><TimeChart data={a} type="area" height={240}/><div className="panel-foot"><span><span className="legend-dot"/> Unique aircraft per hour</span><Coverage data={a}/></div></section><section className="panel"><div className="panel-header"><div><span className="eyebrow">A DIFFERENT PERSPECTIVE</span><h3>What’s overhead</h3></div><span className="badge mint">TODAY</span></div><Donut rows={a.breakdowns.categories} total={a.total} onClick={name=>explore({category:name,preset:'today'})} height={230}/><div className="subtle panel-foot">Categories reflect Aerodrome metadata.</div></section></div></>}
 <div className="section-heading"><div><span className="eyebrow">CONNECTED WORKSPACE</span><h2>Your receiver, one place</h2></div><button className="button small secondary" onClick={()=>navigate('settings')}><SlidersHorizontal size={14}/> Customise</button></div>
 <div className="service-grid">{settings?.services.map((s,i)=>{const serviceIcons:Record<string,typeof Plane>={plane:Plane,chart:BarChart3,map:Map,activity:Activity,radio:Radio,terminal:Terminal,radar:Radar,link:Link};const Icon=serviceIcons[s.icon]||Link;return s.url?<a className="service-card" key={s.id} href={s.url} target="_blank" rel="noopener noreferrer"><div className={'service-icon service-color-'+i%4}><Icon size={24}/></div><ArrowUpRight size={17} className="service-arrow"/><h3>{s.label}</h3><p>{s.description}</p><span className="service-url">{s.url.replace(/^https?:\/\//,'').replace(/\/$/,'')}</span></a>:<button className="service-card" key={s.id} onClick={()=>navigate('settings')}><div className="service-icon"><Icon size={24}/></div><Plus className="service-arrow" size={17}/><h3>{s.label}</h3><p>Set up this shortcut in Settings</p><span className="service-url">URL not configured</span></button>;})}</div>
 <SavedViews explore={explore}/><div className="insight-banner"><div className="service-icon"><Waypoints size={23}/></div><div><h3>There’s a pattern in every passage.</h3><p>Explore weekday rhythms, compare periods, and find your busiest hours.</p></div><button className="button secondary" onClick={()=>navigate('patterns')}>Discover patterns <ArrowRight size={16}/></button></div>
 </>;
}
function Stats({data,onMetric}:{data:Analytics;onMetric?:(metric:Filters['metric'])=>void}){const items:[string,number|null,string,Filters['metric']?][]=[['Unique aircraft',data.summary.aircraft,'Distinct ICAO identities','aircraft'],['Estimated sessions',data.summary.sessions,'Observed session starts','sessions'],['Recorded observations',data.summary.observations,'Sampled snapshots · not RF messages','observations'],['Peak concurrent',data.summary.peak_concurrent,'Aircraft in a recorded minute']];return <div className="stats-grid">{items.map(([label,value,meta,metric],i)=><button key={label} className={'stat-card stat-'+i} onClick={()=>metric&&onMetric?.(metric)} disabled={!metric||!onMetric}><div className="stat-label">{label}<span>{i===0?<Plane size={17}/>:i===1?<Waypoints size={17}/>:i===2?<Database size={17}/>:<Activity size={17}/>}</span></div><div className="stat-value">{number(value)}</div><div className="stat-meta">{meta}</div></button>)}</div>;}
function Coverage({data}:{data:Analytics}){return <span className={'badge '+(data.coverage.pct>=95?'mint':'amber')} title={data.coverage.method}>{number(data.coverage.pct)}% recorded coverage</span>;}
function Warnings({data,hideHeatmapWarning=false}:{data:Analytics;hideHeatmapWarning?:boolean}){const warnings=[...new Set([...(data.warnings||[]),...(data.coverage.warnings||[])])].filter(w=>!hideHeatmapWarning||!w.toLowerCase().includes('heatmap requires hourly grouping'));return <>{warnings.length>0&&<Notice>{warnings.join(' ')}</Notice>}</>;}
function FiltersPanel({value,onApply,status,patterns=false}:{value:Filters;onApply:(f:Filters)=>void;status:Status|null;patterns?:boolean}){
 const [draft,setDraft]=useState(value);const [advanced,setAdvanced]=useState(false);const [error,setError]=useState('');useEffect(()=>setDraft(value),[value]);const set=(k:keyof Filters,v:unknown)=>setDraft(x=>({...x,[k]:v}));
 return <form className="filter-panel panel" onSubmit={e=>{e.preventDefault();try{windowFor(draft,status);onApply(draft);setError('');}catch(e){setError((e as Error).message);}}}><div className="control-row filter-top"><div className="metric-switch" aria-label="Measurement">{(['aircraft','sessions','observations'] as const).map(m=><button type="button" key={m} className={draft.metric===m?'selected':''} onClick={()=>set('metric',m)}>{m==='aircraft'?<Plane size={15}/>:m==='sessions'?<Waypoints size={15}/>:<Database size={15}/>}<span>{m==='aircraft'?'Aircraft':m==='sessions'?'Est. sessions':'Observations'}</span></button>)}</div><button type="button" className={'button small '+(advanced?'primary':'secondary')} onClick={()=>setAdvanced(!advanced)}><SlidersHorizontal size={14}/> Filters <ChevronDown size={14}/></button></div><div className="control-grid">
 <Field label="Time window"><select value={draft.preset} onChange={e=>set('preset',e.target.value)}><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="24">Last 24 hours</option><option value="46">Last 46 hours</option><option value="72">Last 72 hours</option><option value="168">Last 7 days</option><option value="720">Last 30 days</option><option value="week">This week</option><option value="month">This month</option><option value="year">This year</option><option value="all">All available history</option><option value="rolling">Custom rolling duration</option><option value="custom">Custom dates</option></select></Field>
 <Field label={patterns?'Pattern':'Group by'}><select value={draft.group} onChange={e=>set('group',e.target.value)}>{Object.entries({hour:'Hour',day:'Day',week:'ISO week',month:'Calendar month',year:'Year',weekday:'Day of week',hour_of_day:'Hour of day',month_of_year:'Month of year'}).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field>
 <Field label="Statistic"><select value={draft.stat} onChange={e=>set('stat',e.target.value)}><option value="count">Count</option><option value="average">Average per recorded period</option><option value="cumulative">Cumulative bucket total</option><option value="moving_average">Moving average (7 buckets)</option></select></Field><button type="submit" className="button primary apply-button">Apply view <ArrowRight size={16}/></button></div>
 {draft.preset==='rolling'&&<div className="control-row"><Field label="Last"><input type="number" min="1" max="100000" required value={draft.duration} onChange={e=>set('duration',e.target.value)}/></Field><Field label="Unit"><select value={draft.unit} onChange={e=>set('unit',e.target.value)}><option>hours</option><option>days</option><option>weeks</option></select></Field></div>}
 {draft.preset==='custom'&&<div className="control-row"><Field label="From · Europe/London"><input type="datetime-local" required value={draft.start} onChange={e=>set('start',e.target.value)}/></Field><Field label="Until · Europe/London (exclusive)"><input type="datetime-local" required value={draft.end} onChange={e=>set('end',e.target.value)}/></Field><Field label="Repeated autumn hour"><select value={draft.fold||'earlier'} onChange={e=>set('fold',e.target.value)}><option value="earlier">First occurrence · BST (UTC+1)</option><option value="later">Second occurrence · GMT (UTC+0)</option></select></Field></div>}
 {advanced&&<div className="control-grid advanced-grid"><Field label="Aviation category"><select value={draft.category} onChange={e=>set('category',e.target.value)}><option value="">All categories</option>{['commercial','general_aviation','military','helicopter','unknown'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Aircraft type"><input placeholder="e.g. A320" value={draft.aircraft_type} onChange={e=>set('aircraft_type',e.target.value.toUpperCase())}/></Field><Field label="Operator"><input placeholder="All operators" value={draft.operator} onChange={e=>set('operator',e.target.value)}/></Field><Field label="ICAO address"><input placeholder="e.g. 400ABC" value={draft.icao} maxLength={6} onChange={e=>set('icao',e.target.value.toUpperCase())}/></Field><Field label="Callsign prefix"><input placeholder="e.g. BAW" value={draft.callsign} onChange={e=>set('callsign',e.target.value.toUpperCase())}/></Field><Field label="Calendar month"><select value={draft.month} onChange={e=>set('month',e.target.value)}><option value="">Every month</option>{Array.from({length:12},(_,i)=><option key={i} value={i+1}>{new Date(2025,i,1).toLocaleString('en-GB',{month:'long'})}</option>)}</select></Field><Field label="Session idle gap · minutes"><input type="number" min="1" max="240" value={draft.session_gap} onChange={e=>set('session_gap',Number(e.target.value))}/></Field><label className="check-field"><input type="checkbox" checked={draft.exclude_partial} onChange={e=>set('exclude_partial',e.target.checked)}/> Exclude partial boundary periods from averages</label><button type="button" className="button small secondary" onClick={()=>setDraft({...defaults,preset:draft.preset})}>Reset filters</button></div>}
 <div className="filter-definition"><Info size={14}/><span>{metricHelp[draft.metric]}</span></div><div className="active-filters">{(['category','aircraft_type','operator','icao','callsign','month'] as const).filter(k=>value[k]).map(k=><button className="chip" type="button" key={k} onClick={()=>onApply({...value,[k]:''})}>{k.replaceAll('_',' ')}: {value[k]} <X size={11}/></button>)}</div>{error&&<Notice error>{error}</Notice>}</form>;
}
interface ExplorerProps {filters:Filters;status:Status|null;apply:(f:Filters)=>void;tick:number;openAircraft:(s:string)=>void}
function Explorer({filters,status,apply,tick,openAircraft,toast}:{toast:(s:string)=>void}&ExplorerProps){const result=useAnalytics(filters,status,tick);const [chart,setChart]=useState('area');const a=result.data;const update=(partial:Partial<Filters>)=>apply({...filters,...partial});let exportQuery='';try{exportQuery=query(filterParams(filters,status));}catch{/* rendered error below */}
 return <><PageHeading eyebrow="GO BEYOND THE LIVE MAP" title="Explore your airspace" description="Choose a measurement. Shape a window. Find the story." actions={<><button className="button small secondary" onClick={()=>{saveView(filters);toast('Saved views are kept on this browser');}}><Bookmark size={15}/> Save</button><button className="button small secondary" onClick={async()=>{try{await navigator.clipboard.writeText(location.href);toast('View link copied');}catch{toast('Copy the address bar to share this view');}}}><Share2 size={15}/> Share</button></>}/><FiltersPanel value={filters} onApply={apply} status={status}/><LoadState loading={result.loading} error={result.error}/>{a&&!result.error&&<><Warnings data={a}/><Stats data={a} onMetric={metric=>update({metric})}/><section className="panel"><div className="panel-header"><div><span className="eyebrow">{dateTime(a.start)} — {dateTime(a.end)}</span><h3>{metricName[filters.metric]} <span className="subtle">by {filters.group.replaceAll('_',' ')}</span></h3></div><div className="panel-actions"><select aria-label="Chart style" value={chart} onChange={e=>setChart(e.target.value)}><option value="area">Area</option><option value="line">Line</option><option value="bar">Bars</option></select><a className="icon-button" href={'/api/analytics/export?'+exportQuery} aria-label="Export chart data CSV"><ArrowDownToLine size={17}/></a></div></div><TimeChart data={a} type={chart} height={340} onClick={i=>{const b=a.series[i];if(!b?.start||!b?.end)return;update({preset:'custom',start:londonInput(b.start),end:londonInput(b.end),group:filters.group==='year'?'month':filters.group==='month'?'day':'hour'});}}/><div className="panel-foot"><span>Drag to zoom · click a period to drill in · gaps mean unrecorded history</span><Coverage data={a}/></div></section><div className="chart-grid breakdown-grid"><BreakdownPanel title="Aircraft types" rows={a.breakdowns.types} onClick={name=>update({aircraft_type:name})}/><BreakdownPanel title="Operators" subtitle={`${number(a.summary.operator_known_pct)}% metadata coverage`} rows={a.breakdowns.operators} onClick={name=>update({operator:name})}/><section className="panel"><div className="panel-header"><div><h3>Aviation categories</h3><p className="subtle">Click a category to filter</p></div></div><Donut rows={a.breakdowns.categories} total={a.total} onClick={name=>update({category:name})}/></section></div><SeriesTable data={a}/><section className="panel aircraft-lookup"><div><h3>Follow an aircraft’s history</h3><p className="subtle">Inspect recorded observations, metadata and source fields.</p></div><AircraftSearch onSelect={openAircraft}/></section></>}</>;
}
function PageHeading({eyebrow,title,description,actions}:{eyebrow:string;title:string;description:string;actions?:ReactNode}){return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}<span className="text-mint">.</span></h1><p>{description}</p></div>{actions&&<div className="heading-actions">{actions}</div>}</div>;}
function TimeChart({data,type,height=300,onClick,second}:{data:Analytics;type:string;height?:number;onClick?:(i:number)=>void;second?:Analytics}){const option=useMemo(()=>({...chartBase,tooltip:{...chartBase.tooltip,trigger:'axis'},legend:second?{data:['Period A','Period B'],textStyle:{color:'#92a0b1'},top:0}:undefined,xAxis:{type:'category',boundaryGap:type==='bar',data:data.series.map(x=>x.label),axisLine:{lineStyle:{color:'#2a3543'}},axisTick:{show:false},axisLabel:{color:'#91a0b2',hideOverlap:true}},yAxis:{type:'value',min:0,splitLine:{lineStyle:{color:'rgba(130,150,175,.10)'}},axisLabel:{color:'#91a0b2'}},dataZoom:[{type:'inside',filterMode:'none'},{type:'slider',height:13,bottom:2,borderColor:'transparent',fillerColor:'rgba(169,238,213,.12)',dataBackground:{lineStyle:{color:'#47586a'},areaStyle:{color:'#273647'}},handleStyle:{color:'#a9eed5'},textStyle:{color:'#91a0b2'}}],grid:{...chartBase.grid,bottom:48},series:[{name:second?'Period A':metricName[data.metric],type:type==='bar'?'bar':'line',smooth:.25,showSymbol:data.series.length<16,symbolSize:5,connectNulls:false,barMaxWidth:35,lineStyle:{width:2.5},areaStyle:type==='area'?{color:'rgba(169,238,213,.10)'}:undefined,data:data.series.map(x=>x.value),itemStyle:{color:palette[0],borderRadius:type==='bar'?[4,4,0,0]:undefined}},...(second?[{name:'Period B',type:'line',smooth:.25,showSymbol:false,connectNulls:false,lineStyle:{width:2,type:'dashed'},itemStyle:{color:palette[1]},data:second.series.map(x=>x.value)}]:[])]}),[data,type,second]);return <Chart option={option} height={height} label={`${metricName[data.metric]} time chart; accessible values follow below`} onClick={onClick?(i)=>onClick(i):undefined}/>;}
function Donut({rows,total,onClick,height=270}:{rows:Breakdown[];total:number;onClick?:(name:string)=>void;height?:number}){return <Chart height={height} label="Category distribution; category table available in the database and explorer" option={{...chartBase,tooltip:{...chartBase.tooltip,trigger:'item',formatter:'{b}: {c} ({d}%)'},legend:{bottom:0,type:'plain',width:'100%',itemGap:12,textStyle:{color:'#92a0b1',fontSize:11},icon:'circle',itemWidth:7,itemHeight:7},graphic:[{type:'text',left:'center',top:'34%',style:{text:number(total),fill:'#dce7ee',font:'600 27px system-ui',textAlign:'center'}},{type:'text',left:'center',top:'48%',style:{text:'in selected window',fill:'#92a0b1',font:'11px system-ui',textAlign:'center'}}],series:[{type:'pie',radius:['56%','73%'],center:['50%','43%'],avoidLabelOverlap:true,padAngle:3,itemStyle:{borderRadius:5},label:{show:false},data:rows.map(x=>({name:x.name.replaceAll('_',' '),value:x.value})),emphasis:{scaleSize:4,label:{show:false}}}]}} onClick={(_,name)=>{const row=rows.find(x=>x.name.replaceAll('_',' ')===name);if(row)onClick?.(row.name);}}/>;}
function BreakdownPanel({title,subtitle,rows,onClick}:{title:string;subtitle?:string;rows:Breakdown[];onClick:(s:string)=>void}){const max=Math.max(1,...rows.map(r=>r.value));return <section className="panel"><div className="panel-header"><div><h3>{title}</h3><p className="subtle">{subtitle||'Click a row to filter this view'}</p></div></div><div className="breakdown-list">{rows.slice(0,10).map((r,i)=><button className="breakdown-row" key={r.name} onClick={()=>onClick(r.name)}><span className="breakdown-label"><i style={{background:palette[i%palette.length]}}/>{r.name.replaceAll('_',' ')}</span><strong>{number(r.value)}</strong><span className="breakdown-track"><i style={{width:`${r.value/max*100}%`,background:palette[i%palette.length]}}/></span></button>)}{rows.length===0&&<p className="subtle">No classified records in this period.</p>}</div></section>;}
